#include <string>

class CargoTag {
public:
    CargoTag(std::string code, int priority)
        : code_(code), priority_(priority) {}

    void rename(const std::string& newCode) {
        code_ = newCode;
    }

    void addPriority(int amount) {
        priority_ += amount;
    }

    const std::string& code() const {
        return code_;
    }

    int priority() const {
        return priority_;
    }

private:
    std::string code_;
    int priority_;
};

class DockConsole {
public:
