    void assign(CargoTag* tag) {
        active_ = nullptr;
    }

    void clear() {
    }

    bool hasActive() const {
        return active_ != nullptr;
    }

    std::string activeCode() const {
        return active_ == nullptr ? "No active cargo" : active_->code();
    }

    int activePriority() const {
        return active_ == nullptr ? -1 : active_->priority();
    }

    void boostPriority(int amount) {
        if (active_ != nullptr) {
            active_->addPriority(amount);
        }
    }

private:
    CargoTag* active_;
};

